import sys

def main():
    d = int(sys.stdin.read().split()[0])
    MOD = 10**9 + 7
    # bit (k - 2) of a mask is set once digit k (2..9) has been placed; 0 and 1 never matter later
    def moves(mask):
        res = {mask: 1}  # placing a 0 keeps the mask
        for n in range(2, 10):
            if any((mask >> (k - 2)) & 1 and n % k == 0 for k in range(2, n + 1)):
                m2 = mask | (1 << (n - 2))
                res[m2] = res.get(m2, 0) + 1
        return list(res.items())
    trans = {}
    dp = {0: 1}  # first digit 1
    for n in range(2, 10):
        dp[1 << (n - 2)] = 1  # first digit n
    for _ in range(d - 1):
        nd = {}
        for m, v in dp.items():
            if m not in trans:
                trans[m] = moves(m)
            for m2, c in trans[m]:
                nd[m2] = (nd.get(m2, 0) + v * c) % MOD
        dp = nd
    print(sum(dp.values()) % MOD)

