MOD = 10**9 + 7

def ok(n, placed):
    if n == 0:
        return True
    return any(k in placed for k in range(2, 10) if n % k == 0)

if d <= 6:
    total = 0
    def rec(seq):
        global total
        if len(seq) == d:
            total += 1
            return
        for n in range(10):
            if n == 0 and not seq:
                continue
            if not seq or ok(n, set(seq)):
                rec(seq + [n])
    rec([])
    print(total % MOD)
else:
    dp = {}
    for n in range(1, 10):
        dp[frozenset([n])] = dp.get(frozenset([n]), 0) + 1
    for _ in range(d - 1):
        nd = {}
        for placed, v in dp.items():
            for n in range(10):
                if ok(n, placed):
                    key = placed | {n}
                    nd[key] = (nd.get(key, 0) + v) % MOD
